effect.shader:

    vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord.xy

   /////////////////////////

          float hash11(float a)
        {
            return fract(53.156*sin(a*45.45))-.5;
        }
        float dispnoise(float a)
        {
            float a1 = hash11(floor(a)),a2=hash11(ceil(a));
            return .03*mix(a1,a2,pow(fract(a),8.));
        }
        float noise(float a)
        {
            float a1 = hash11(floor(a)),a2=hash11(ceil(a));
            return mix(a1+.5,a2+.5,pow(fract(a),50.));
        }

        float hash21(vec2 a)
        {
            return fract(sin(dot(a,vec2(12.9898,78.233))+progress)*43758.5453);
        }
        float perlin(vec2 a)
        {
            a*=vec2(100.,500.);
            float a1 = hash21(floor(a));
            float a2 = hash21(floor(a)+vec2(1,0));
            float a3 = hash21(floor(a)+vec2(0,1));
        	float a4 = hash21(ceil(a));
         	return pow(mix(mix(a1,a2,fract(a.x)),mix(a3,a4,fract(a.x)),fract(a.y)),2.);  
        }


        vec4 grade(vec4 color)
        {
         	color = pow(color,vec4(2.2));
            color*= vec4(1.3,.7,.89,1);

            color = pow(color,vec4(.4));
            return 1.3*color;
        }

   /////////////////////////
    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;
        vec2 image_size = getTexSize(inputImg.size);
        float maxF = max(acScreenSize.x, acScreenSize.y);
        vec2 texelSize = 1.0 / vec2(maxF, maxF);

        // vec2 TanRyu;
        // TanRyu = acScreenNorm; 

        vec2 TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        TanRyu.y *=acLayerSize.y/acLayerSize.x;

        // TanRyu /= scale;
        // TanRyu *= rot2m((0.0+angle)*0.0174533);

        vec2 scaleVec;
        scaleVec = vec2(scale*stretch.x,scale*stretch.y);
        TanRyu /= scaleVec;

        TanRyu += vec2((-375.0+position.x), ((progress*50.0)+position.y))*vec2(-1.,1.)/500.;

        // float cx = 0.5 + acLayerPivot.x/acLayerSize.x;
        // float cy = 0.5 - acLayerPivot.y/acLayerSize.y;

        /////////////////////////

    	vec4 fragColor;

            vec2 uv = TanRyu;
            // vec2 uv = fragCoord.xy / iResolution.xy;
            float disp = dispnoise(.7*uv.y+mod(progress,200.)*.2);
            uv.x+=disp;
            	if(hash11(floor(progress*4.)/4.)>.47)
        		uv.y+=.5*hash11(floor(progress*8.)/4.);
            uv =fract(uv);

            vec4 color  = vec4(0,0,0,1);
            // vec4 color  = texture2DCv(inputImg.texture,uv);

            color = grade(color);
             if(hash11(uv.y+floor((progress+uv.y)*16.)/16.)>.497)
                 color+=hash11(floor(100.*(uv.x-progress)))+.5;
         	color = mix(color,vec4(.3),max(0.,sin(uv.y*20.)*perlin(.3*uv)*.5));


             fragColor = color;
             if(abs(TanRyu.y)>acScreenSize.y-50.*noise(5.*progress+(uv.y>.5?0.:10.)))
             // if(abs(2.*fragCoord.y-acScreenSize.y)>acScreenSize.y-50.*noise(5.*progress+(uv.y>.5?0.:10.)))
             fragColor=vec4(perlin(uv)+.5);

            const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
            vec4 gradmap;
            float luminance = dot(fragColor.rgb, luminanceWeighting);
            gradmap = mix(color1,color2,luminance)*fragColor.a;

    	vec4 factor = mix(texColorX,gradmap,1.0);

        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            resultfinal = (factor * bright) * texColor.a;
            // resultfinal = (newLayer(texColor, factor) * bright) * texColor.a;
        } else if( blendMode==1 ) {         // multiply
            factor *= bright;
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            factor *= bright;
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	gl_FragColor = mix(texColor, resultfinal, alpha);
    	// }
    }
